        var unitPos = RadiansToPointOnSphere(EquitorialCoordsToRadians(rosetteRAs[i], rosetteDECs[i]));
        positions.push(unitPos[0] * (1 / (rosetteParallaxes[i] * 0.001)) * 0.1);
        positions.push(unitPos[1] * (1 / (rosetteParallaxes[i] * 0.001)) * 0.1);
